import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_public(path: str) -> str:
    """Return the text of the file at request path `path` inside the
    directory `notes` (relative to the current working directory).

    `path` is untrusted. It is interpreted relative to `notes`. Segments
    like `sub/../a.txt` that wander but stay inside `notes` are allowed.

    Returns "" when:
      * the path leaves `notes` (e.g. `..`, `../x`, `sub/../../x`), or is
        absolute, or contains a NUL byte;
      * the path resolves (including through symlinks) to anything outside
        `notes`;
      * the target is missing, is not a regular file (e.g. a directory,
        including `notes` itself), or cannot be read or decoded as UTF-8.

    Never raises for bad names or unreadable files, and never reads a file
    outside `notes`.
    """
    if "\x00" in path:
        return ""
    try:
        requested = Path(path)
        if requested.is_absolute() or requested.anchor or requested.drive:
            return ""
        root = Path(NOTES_DIR).resolve()
        candidate = (root / requested).resolve()
        if not candidate.is_relative_to(root):
            return ""
        if not candidate.is_file():
            return ""
        return candidate.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError, UnicodeError):
        return ""


@pytest.fixture
def tree(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("SIBLING", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(tree: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_reads_nested_file(tree: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wandering_path_staying_inside_is_ok(tree: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"


def test_missing_file_is_empty(tree: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_directory_and_empty_path_are_empty(tree: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_parent_traversal_is_empty(tree: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../x") == ""
    assert read_public("../../../../../../etc/passwd") == ""


def test_sibling_directory_with_shared_prefix_is_empty(tree: Path) -> None:
    assert read_public("../notes2/x.txt") == ""


def test_absolute_paths_are_empty(tree: Path) -> None:
    assert read_public(str(tree / "secret.txt")) == ""
    assert read_public(str(tree / NOTES_DIR / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("/") == ""


def test_nul_byte_is_empty(tree: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a.txt\x00../secret.txt") == ""


def test_symlink_escaping_notes_is_empty(tree: Path) -> None:
    link = tree / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(tree / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("link.txt") == ""


def test_symlinked_directory_escaping_notes_is_empty(tree: Path) -> None:
    link = tree / NOTES_DIR / "outdir"
    try:
        link.symlink_to(tree / "notes2", target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("outdir/x.txt") == ""


def test_symlink_staying_inside_notes_is_ok(tree: Path) -> None:
    link = tree / NOTES_DIR / "alias.txt"
    try:
        link.symlink_to(tree / NOTES_DIR / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("alias.txt") == "alpha"


def test_undecodable_file_is_empty(tree: Path) -> None:
    (tree / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_public("bin.dat") == ""


def test_unreadable_file_is_empty(tree: Path) -> None:
    target = tree / NOTES_DIR / "locked.txt"
    target.write_text("hidden", encoding="utf-8")
    target.chmod(0o000)
    try:
        if os.access(target, os.R_OK):
            pytest.skip("permissions not enforced (running as root?)")
        assert read_public("locked.txt") == ""
    finally:
        target.chmod(0o600)


def test_does_not_raise_on_odd_names(tree: Path) -> None:
    for name in ["a" * 5000, "\n", " ", "a.txt/", "a.txt/.."]:
        assert isinstance(read_public(name), str)
